import { useAuth } from "../auth/AuthContext";
import { useEffect, useState } from "react";

export default function Dashboard() {
  const { user } = useAuth();
  const [students, setStudents] = useState([]);

  const [showForm, setShowForm] = useState(false);
  const [newUser, setNewUser] = useState({ username: "", password: "" });

  useEffect(() => {
    if (user?.role === "teacher") {
      fetch(`http://localhost:3001/students?teacher=${user.username}`)
        .then((res) => res.json())
        .then((data) => setStudents(data))
        .catch((err) =>
          console.error("Fehler beim Laden der Schülerdaten:", err)
        );
    }
  }, [user]);

  return (
    <div>
      <h1 className="text-2xl font-bold mb-4 heading-style">Lehrer-Dashboard</h1>

      <table className="table-auto border border-white w-full text-sm text-style">
        <thead>
          <tr>
            <th className="border px-2 py-1">Benutzername</th>
            <th className="border px-2 py-1">Level 1</th>
            <th className="border px-2 py-1">Level 2</th>
            <th className="border px-2 py-1">Level 3</th>
          </tr>
        </thead>
        <tbody>
          {students.map((s, i) => (
            <tr key={i}>
              <td className="border px-2 py-1">{s.username}</td>
              <td className="border px-2 py-1">{s.progress.level1Passed ? "✅" : "❌"}</td>
              <td className="border px-2 py-1">{s.progress.level2Passed ? "✅" : "❌"}</td>
              <td className="border px-2 py-1">{s.progress.level3Passed ? "✅" : "❌"}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="flex justify-end">
      <button
        onClick={() => setShowForm(true)}
        className="text-sm px-3 py-1 border border-white text-white rounded hover:bg-white hover:text-black transition"
      >
        + Schüler/-in hinzufügen
      </button>
    </div>

        {showForm && (
          <div className="mt-4 space-y-2 max-w-xs">
            <input
              type="text"
              placeholder="Benutzername"
              value={newUser.username}
              onChange={(e) => setNewUser({ ...newUser, username: e.target.value })}
              className="input-style w-full"
            />
            <input
              type="password"
              placeholder="Passwort"
              value={newUser.password}
              onChange={(e) => setNewUser({ ...newUser, password: e.target.value })}
              className="input-style w-full"
            />
            <button
              onClick={async () => {
                const res = await fetch("http://localhost:3001/students", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({
                    ...newUser,
                    teacher: user.username,
                  }),
                });

                if (res.ok) {
                  const { student } = await res.json();
                  setStudents((prev) => [...prev, student]);
                  setShowForm(false);
                  setNewUser({ username: "", password: "" });
                } else {
                  alert("Fehler beim Anlegen – Name evtl. schon vergeben?");
                }
              }}
              className="px-4 py-1 border border-white text-white rounded hover:bg-white hover:text-black transition"
            >
              Schüler/in anlegen
            </button>
          </div>
        )}
    </div>
  );
}
